from returns.result import Failure, Result, Success, safe

@safe                          # a throwing function becomes one returning Result
def parse_port(text: str) -> int:
    port = int(text)
    if not 1 <= port <= 65535:
        raise ValueError(f"port out of range: {port}")
    return port

match parse_port(raw):
    case Success(value): print("port", value)
    case Failure(error): print("invalid:", error)
